// The single catalogue of Phase 1 sounds: used by the audio engine, the sound test page
// (plan 01-09) and the licence check (plan 01-11). Every sound is generated by code today
// (D-22: no CC0 recording confirmed); recorded candidates are optional upgrades.

export type SoundId =
  | "sabot"
  | "hennissement-sortie"
  | "hennissement-ruade"
  | "hennissement-plainte"
  | "hennissement-joyeux"
  | "hennissement-fete"
  | "hennissement-surpris"
  | "carte-donne"
  | "carte-pose"
  | "carte-echange"
  | "ambiance";

/** Mix bus a sound plays on (the master bus sits above both). */
export type SoundBus = "sfx" | "ambience";

/** Name of the synthesis recipe in synth.ts that renders the sound. */
export type SynthRecipe =
  | "hoof"
  | "neigh-sortie"
  | "neigh-ruade"
  | "neigh-plainte"
  | "neigh-joyeux"
  | "neigh-fete"
  | "neigh-surpris"
  | "card-donne"
  | "card-pose"
  | "card-echange"
  | "ambience";

export type SoundDef = {
  bus: SoundBus;
  synth: SynthRecipe;
  /** Number of synthesized variants played round-robin (3 hoof clops, 1 for everything else). */
  variants: number;
  /** Optional recorded candidates under /audio/ (.m4a and .mp3); empty today. */
  files: string[];
};

export const SOUNDS: Record<SoundId, SoundDef> = {
  sabot: { bus: "sfx", synth: "hoof", variants: 3, files: [] },
  "hennissement-sortie": { bus: "sfx", synth: "neigh-sortie", variants: 1, files: [] },
  "hennissement-ruade": { bus: "sfx", synth: "neigh-ruade", variants: 1, files: [] },
  "hennissement-plainte": { bus: "sfx", synth: "neigh-plainte", variants: 1, files: [] },
  "hennissement-joyeux": { bus: "sfx", synth: "neigh-joyeux", variants: 1, files: [] },
  "hennissement-fete": { bus: "sfx", synth: "neigh-fete", variants: 1, files: [] },
  "hennissement-surpris": { bus: "sfx", synth: "neigh-surpris", variants: 1, files: [] },
  "carte-donne": { bus: "sfx", synth: "card-donne", variants: 1, files: [] },
  "carte-pose": { bus: "sfx", synth: "card-pose", variants: 1, files: [] },
  "carte-echange": { bus: "sfx", synth: "card-echange", variants: 1, files: [] },
  ambiance: { bus: "ambience", synth: "ambience", variants: 1, files: [] },
};

export const SOUND_IDS = Object.keys(SOUNDS) as SoundId[];
